package com.ruoyi.medical.persistence;
import com.ruoyi.medical.contracts.*;
import com.ruoyi.medical.identity.*;
import org.springframework.mock.web.*;
import org.springframework.beans.factory.ListableBeanFactory;
import org.springframework.security.core.Authentication;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.core.env.MapPropertySource;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.ruoyi.medical.persistence.VerificationInputFixture.*;
final class ModelEnablementPolicyHttpTest {
 ModelEnablementPolicyPreparationTest.Fixture x;VerificationInputFixture f;ApplicationSessionIdentity identity;Authentication authentication;ModelEnablementPolicyController controller;
 @BeforeEach void setup()throws Exception{x=new ModelEnablementPolicyPreparationTest.Fixture();f=x.f;identity=mock(ApplicationSessionIdentity.class);authentication=mock(Authentication.class);when(identity.requireCurrent(any(),eq(authentication))).thenReturn(f.subject);controller=new ModelEnablementPolicyController(identity,x.service,x.schema,f.json);}
 @AfterEach void cleanup()throws Exception{if(f!=null)f.close();}
 MockHttpServletRequest request(boolean write)throws Exception{var r=new MockHttpServletRequest();r.addHeader("X-Schema-Version","1.0.0");r.addHeader("X-Context-Revision","1");if(write){r.setMethod("POST");r.setContentType("application/json");r.addHeader("X-CSRF-TOKEN","actual-filter-handles-authentication");r.addHeader("Idempotency-Key",KEY);r.setContent(x.schema.canonical(x.request()).getBytes(StandardCharsets.UTF_8));}return r;}
 @Test void controllerRegistrationAndTypedRecoveryExposeClosedNoStoreEnvelope()throws Exception{var response=new MockHttpServletResponse();var envelope=controller.prepare(request(true),response,authentication);assertEquals(201,response.getStatus());assertEquals("no-store",response.getHeader("Cache-Control"));assertNotNull(response.getHeader("X-Request-Id"));var receipt=envelope.path("data");assertTrue(receipt.has("data_policy_evidence"));var recovered=controller.recover(request(false),new MockHttpServletResponse(),authentication,receipt.path("operation_id").asText());assertEquals(receipt,recovered.path("data").path("receipt"));}
 @Test void missingDuplicateAndCommaHeadersAreRejectedBeforeBodyOrGet()throws Exception{for(String header:java.util.List.of("X-Schema-Version","X-Context-Revision","Idempotency-Key","X-CSRF-TOKEN")){var r=request(true);r.removeHeader(header);assertThrows(SchemaRejection.class,()->controller.prepare(r,new MockHttpServletResponse(),authentication));var duplicate=request(true);duplicate.addHeader(header,"duplicate");assertThrows(SchemaRejection.class,()->controller.prepare(duplicate,new MockHttpServletResponse(),authentication));}assertEquals(0,f.requests.get());}
 @Test void unknownSchemaQueryAndReadBodyAreRejected()throws Exception{var r=request(true);r.removeHeader("X-Schema-Version");r.addHeader("X-Schema-Version","2.0.0");assertThrows(SchemaRejection.class,()->controller.prepare(r,new MockHttpServletResponse(),authentication));var query=request(false);query.setQueryString("purpose=anything");assertThrows(SchemaRejection.class,()->controller.read(query,new MockHttpServletResponse(),authentication,id(808)));var body=request(false);body.setContent("{}".getBytes(StandardCharsets.UTF_8));assertThrows(SchemaRejection.class,()->controller.read(body,new MockHttpServletResponse(),authentication,id(808)));}
 @Test void oversizedRequestIsRejectedBeforeSessionAndTransport()throws Exception{var r=request(true);r.setContent(new byte[8193]);assertEquals(ErrorCode.FILE_TOO_LARGE,assertThrows(TenantAccessException.class,()->controller.prepare(r,new MockHttpServletResponse(),authentication)).code());verifyNoInteractions(identity);assertEquals(0,f.requests.get());}
 @Test void actualSpringConditionalDefaultsDisabledWithoutConstructingDependencies(){try(var context=new AnnotationConfigApplicationContext()){context.register(ModelEnablementPolicyPreparation.class,ModelEnablementPolicyController.class);context.refresh();assertEquals(0,context.getBeanNamesForType(ModelEnablementPolicyPreparation.class).length);assertEquals(0,context.getBeanNamesForType(ModelEnablementPolicyController.class).length);}}
 @Test void actualSpringEnabledControllersResolveAllRealLocalSchemaBeans(){try(var context=new AnnotationConfigApplicationContext()){context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("offline",Map.of("medical.model-enablement-policy-preparation.enabled","true")));context.registerBean(ApplicationSessionIdentity.class,()->identity);context.registerBean(ModelEnablementPolicyPreparation.class,()->x.service);context.registerBean(PermissionSchema.class,()->f.json);context.register(ModelEnablementPolicySchema.class,ModelEnablementPolicyController.class);context.refresh();assertNotNull(context.getBean(ModelEnablementPolicyController.class));assertNotNull(context.getBean(ModelEnablementPolicySchema.class));}}
 @Test void candidatesReadUsesAuthenticatedNoStoreEnvelopeWithoutWrites()throws Exception{var response=new MockHttpServletResponse();var result=controller.candidate(request(false),response,authentication,MODEL);assertEquals("NOT_READ",result.at("/data/original_validation").asText());assertEquals("no-store",response.getHeader("Cache-Control"));assertEquals(0,f.requests.get());assertTrue(f.writes.isEmpty());}
 @Test void errorMappingPreservesSafeStructuredCodes()throws Exception{for(var entry:Map.of(ErrorCode.ACCESS_DENIED,403,ErrorCode.FILE_TOO_LARGE,413,ErrorCode.OBJECT_UNAVAILABLE,404,ErrorCode.CONTENT_MISMATCH,409).entrySet()){var response=new MockHttpServletResponse();controller.failure(new TenantAccessException(entry.getKey()),response);assertEquals(entry.getValue(),response.getStatus());assertFalse(response.getContentAsString().contains("Exception"));}}
}
